<div class="d-flex justify-content-between mb-4"><h1 class="h3">Assuntos</h1><div><a class="btn btn-outline-primary" href="/assuntos/novo">Novo assunto</a> <a class="btn btn-primary" href="#lote">Cadastro em lote</a></div></div>
<div class="table-responsive"><table class="table table-bordered bg-white align-middle"><thead><tr><th>Título</th><th>Configuração</th><th>Ordem</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach ($subjects as $subject): ?><tr><td><?= htmlspecialchars($subject['titulo'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($subject['configuracao_nome'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= (int) $subject['ordem'] ?></td><td><?= htmlspecialchars($subject['status'], ENT_QUOTES, 'UTF-8') ?></td><td><a class="btn btn-sm btn-outline-primary" href="/assuntos/editar?id=<?= (int) $subject['id'] ?>">Editar</a> <form class="d-inline" method="post" action="/assuntos/excluir"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) $subject['id'] ?>"><button class="btn btn-sm btn-outline-danger">Excluir</button></form></td></tr><?php endforeach; ?><?php if (!$subjects): ?><tr><td colspan="5" class="text-center text-muted">Nenhum assunto cadastrado.</td></tr><?php endif; ?></tbody></table></div>
<div id="lote" class="card card-body bg-white mt-4"><h2 class="h5">Cadastro em lote</h2><p class="text-muted">Cole um título por linha. Linhas vazias serão ignoradas.</p><form method="post" action="/assuntos/lote"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><textarea class="form-control mb-3" name="titulos" rows="5" required></textarea><button class="btn btn-primary">Cadastrar assuntos</button></form></div><a class="d-block mt-3" href="/dashboard">Voltar ao dashboard</a>
